import { services, bookingUrl, mapsUrl } from './services.js';
import { brand, needs, campaigns } from './content.js';
import { Navbar, Hero, TreatmentCard, CTASection, FAQ, Footer, LeadForm } from './components.js';
const slug = location.pathname.split('/').filter(Boolean)[1];
const campaign = location.pathname.startsWith('/campanhas/') ? campaigns[slug] : null;
const events = []; // In-memory adapter: no network, personal data, storage or pixels.
const attribution = Object.fromEntries(['utm_source','utm_medium','utm_campaign','utm_content','utm_term'].map(k=>[k,new URLSearchParams(location.search).get(k)?.slice(0,150)]).filter(([,v])=>v));
function track(name, detail={}) { const event={event:name,page:location.pathname,campaign:campaign?.name??null,...detail};events.push(event);window.dispatchEvent(new CustomEvent('aura:analytics',{detail:event})); }
window.auraAnalytics = { events };
const homepage = `<section class="intro section" id="conceito"><p class="eyebrow">ESSÊNCIA AURA</p><h2>Mais do que um cuidado com a beleza.<br>Um cuidado com <em>quem você é.</em></h2><p>Autocuidado, conhecimento técnico e bem-estar se encontram na proposta do AURA. Um olhar para a sua individualidade, com espaço para escutar, entender e respeitar suas escolhas.</p></section><section class="treatments section" id="cuidados"><div class="section-head"><div><p class="eyebrow">ENCONTRE O SEU MOMENTO</p><h2>O que você quer<br>cuidar hoje?</h2></div><p>Comece pelo que faz sentido para você.<br>Os detalhes, a gente conversa depois.</p></div><div class="grid">${needs.map(TreatmentCard).join('')}</div></section><section class="section catalog" id="servicos"><div class="section-head"><div><p class="eyebrow">ESCOLHA SEU CUIDADO</p><h2>Serviços e valores.</h2></div><p>Uma seleção para começar.<br>Todos os serviços estão no Trinks.</p></div><div class="catalog-filters" role="group" aria-label="Filtrar serviços"><button class="filter active" data-filter="Todos" aria-pressed="true">Todos</button>${[...new Set(services.map(s=>s[0]))].map(g=>`<button class="filter" data-filter="${g}" aria-pressed="false">${g}</button>`).join('')}</div><div class="service-grid">${services.map(([group,name,duration,price,id,from])=>`<article class="service" data-group="${group}"><p class="eyebrow">${group} · ${duration}</p><h3>${name}</h3><p class="price">${from?'A partir de ':''}${price.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</p><a class="text-link" data-booking href="${id?'https://www.trinks.com/aura-visage-spa-ltda/escolha-profissional/'+id+'/frameBusca':bookingUrl}" target="_blank" rel="noopener noreferrer">${id?'Ver horários':'Ver no catálogo'} ↗</a></article>`).join('')}</div><p class="form-note">Valores consultados no Trinks em 07/10/2026. Confira o preço e a disponibilidade ao reservar. Serviços sujeitos à avaliação quando aplicável.</p><a class="button" data-booking href="${bookingUrl}" target="_blank" rel="noopener noreferrer">Ver catálogo completo no Trinks ↗</a></section><section class="experience section" id="experiencia"><div><p class="eyebrow">A EXPERIÊNCIA AURA</p><h2>Cada pessoa,<br>um jeito de <em>cuidar.</em></h2><p>Uma pausa na rotina da cidade, com espaço para desacelerar. Cuidado que começa pela escuta e valoriza cada etapa da sua experiência.</p><button class="text-link plain" data-schedule>Conversar sobre meu cuidado</button></div><div class="experience-detail"><figure class="real-space"><img src="/assets/ambiente-aura.jpg" alt="Balanço com almofada e flores diante de uma parede verde, em publicação do AURA" width="361" height="640" loading="lazy"><figcaption><a href="https://www.instagram.com/auravisagespa/reel/DaXgkAQDZr1/" target="_blank" rel="noopener noreferrer">Um olhar para o espaço · Instagram do AURA</a></figcaption></figure><div class="steps">${[['Escutar','Entender seus interesses, suas expectativas e seu momento.'],['Personalizar','Conversar sobre possibilidades, com avaliação e orientação profissional.'],['Acompanhar','Valorizar a continuidade do cuidado e esclarecer suas dúvidas.']].map(([h,p],i)=>`<div class="step"><span>0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div></div></section><section class="trust section" id="avaliacoes"><div><p class="eyebrow">ATENDIMENTO COM PRESENÇA</p><h2>Uma equipe para<br>receber você.</h2><p>Conheça os profissionais disponíveis para cada serviço ao reservar pelo Trinks. Para dúvidas e orientação de agendamento, converse com Yasmin na recepção.</p><button class="text-link plain" data-schedule>Falar com a recepção</button></div><div><p class="eyebrow">EXPERIÊNCIAS REAIS</p><h2>O cuidado também<br>se conta.</h2><p>Veja as avaliações de quem já visitou o AURA no Google. Depois da sua visita, compartilhe sua experiência por lá ou pela plaqueta disponível na recepção.</p><a class="text-link" href="https://maps.app.goo.gl/GHGCdXDooDebd7qG9" target="_blank" rel="noopener noreferrer">Ver o AURA e suas avaliações no Google ↗</a></div></section>${CTASection()}<section class="contact section" id="contato"><div><p class="eyebrow">ENCONTRE O AURA</p><h2>Um espaço para<br>o seu cuidado.</h2><dl><dt>Endereço</dt><dd>${brand.address??'Endereço oficial a confirmar.'}</dd><dt>Horários</dt><dd>${brand.hours??'Dias e horários a confirmar.'}</dd><dt>Contato</dt><dd>${brand.whatsappLabel??'WhatsApp oficial a confirmar.'}</dd></dl></div><div class="location-note"><p class="eyebrow">SUA VISITA COMEÇA AQUI</p><h3>Vamos nos encontrar?</h3><p>Estamos na Rua Pascoal Souza, 66, na Vila Maria Luísa — Bairro do Limão.</p><p><a class="text-link" href="https://maps.app.goo.gl/GHGCdXDooDebd7qG9" target="_blank" rel="noopener noreferrer">Abrir o AURA no Google Maps ↗</a></p><button class="button" data-schedule>Preparar minha avaliação</button></div></section>${FAQ()}`;
document.querySelector('#app').innerHTML = `${Navbar()}<main>${Hero(campaign)}${campaign?`<p class="campaign-note">Conceito de campanha para revisão. Serviços, condições e disponibilidade ainda não definidos.</p><section class="intro section"><p class="eyebrow">${campaign.name}</p><h2>O cuidado começa com a sua escolha.</h2><p>Converse com o AURA para conhecer as possibilidades e confirmar disponibilidade.</p></section>${CTASection()}${FAQ()}`:`<div class="values"><span>ESCUTA & ACOLHIMENTO</span><span>CUIDADO INDIVIDUAL</span><span>BELEZA & BEM-ESTAR</span></div>${homepage}`}</main>${Footer()}<button class="mobile-cta button" data-schedule>Agendar minha avaliação</button>${LeadForm()}`;
if(campaign){document.title=`${campaign.name} | Aura Visage Spa`;document.querySelector('meta[name="description"]').content=campaign.text;document.querySelector('meta[property="og:title"]').content=document.title;document.querySelector('meta[property="og:description"]').content=campaign.text;}
const lead = document.querySelector('#lead-dialog');
const form = document.querySelector('#lead-form');
function schedule(interest=campaign?.interest??'Autocuidado') { document.querySelectorAll('dialog[open]').forEach(d=>d.close());form.elements.interest.value=needs.some(n=>n.name===interest)?interest:"Autocuidado";lead.showModal();track('click_schedule',{interest}); }
document.querySelectorAll('[data-schedule]').forEach(b=>b.addEventListener('click',()=>schedule()));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.querySelector('[data-privacy]').addEventListener('click',()=>document.querySelector('#privacy-dialog').showModal());
const menu = document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open);});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open');}));
document.querySelectorAll('[data-treatment]').forEach(b=>b.addEventListener('click',()=>{const item=needs[Number(b.dataset.treatment)];document.querySelector('#detail-title').textContent=item.label;document.querySelector('#detail-text').textContent=item.detail;document.querySelector('#detail-cta').onclick=()=>schedule(item.name);document.querySelector('#detail-dialog').showModal();track('view_treatment',{interest:item.name});}));
let started=false;form.addEventListener('input',()=>{if(!started){track('start_lead');started=true;}document.querySelector('#lead-result').hidden=true;document.querySelector('#lead-status').textContent='';});
form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const digits=String(data.get('phone')).replace(/\D/g,'');if(digits.length<10||digits.length>13){form.elements.phone.setCustomValidity('Informe o número com DDD, entre 10 e 13 dígitos.');form.elements.phone.reportValidity();return;}const source=campaign?`pela campanha ${campaign.name}`:'pelo site';const utm=Object.entries(attribution).map(([k,v])=>`${k}: ${v}`).join('; ');const message=`Olá, conheci o AURA ${source}. Meu nome é ${String(data.get('name')).trim()} e gostaria de saber mais sobre ${data.get('interest')}. Prefiro atendimento: ${data.get('period')}. Meu WhatsApp: ${data.get('phone')}.${utm?' Origem: '+utm:''}`;document.querySelector('#lead-result').hidden=false;document.querySelector('#lead-result textarea').value=message;if(brand.whatsapp){track('whatsapp_message_prepared',{interest:data.get('interest')});track('click_whatsapp');if(campaign)track('campaign_whatsapp_click');window.open(`https://wa.me/${brand.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');document.querySelector('#lead-status').textContent='Pedido preparado. Envie a mensagem no WhatsApp para conversar com o AURA.';}else{document.querySelector('#lead-status').textContent='Mensagem preparada para revisão. Nenhum pedido foi enviado: aguardamos o WhatsApp oficial do AURA.';}});
form.elements.phone.addEventListener('input',()=>form.elements.phone.setCustomValidity(''));
document.querySelector('#copy-message').addEventListener('click',async()=>{const textarea=document.querySelector('#lead-result textarea');try{await navigator.clipboard.writeText(textarea.value);document.querySelector('#lead-status').textContent='Mensagem copiada. Nenhum pedido foi enviado.';}catch{textarea.focus();textarea.select();document.querySelector('#lead-status').textContent='Selecione e copie a mensagem acima.';}});
track('page_view');

document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-group]').forEach(card=>card.hidden=button.dataset.filter!=='Todos'&&card.dataset.group!==button.dataset.filter);}));
document.querySelectorAll('[data-booking]').forEach(link=>link.addEventListener('click',()=>track('click_trinks')));


